css:
/* ==== INTERFACE ====
方向：无摄影依赖的时尚大片编辑语言；超大窄体题名、黑色细规则线、酒红重点与宽阔留白形成封面感，正文、真实数据图和控件保持清晰，不规定每页布局。
token --bg：页面底色。
token --text：正文与主标题色。
token --muted：辅助说明与次级刻度色。
token --focus：键盘焦点色。
token --accent：关键数值与当前交互色。
token --compound：复利曲线色。
token --fixed：固定增加曲线色。
token --font-sans：正文与控件的中英混排字体。
token --font-title：中英展示标题字体。
token --font-number：数字与标签字体。
token --fs-h1/--fs-h2/--fs-lead/--fs-body/--fs-sec/--fs-label/--fs-tick：投影字阶。
class .nt-title：中英混排页标题。
class .nt-body：可投影的中英正文。
class .nt-number：金额、百分比、年份和算式数字。
class .nt-kicker：短栏目名或页码式眉题。
class .nt-rule：编辑式水平分隔线。
class .nt-formula：原生文本公式外观；复杂公式仍交由公式引擎。
class .nt-data-table：真实数值对照表；表头及数值列获得编辑式规则线与等宽数字。
class .nt-growth-chart：挂在 SVG 上启用网格、坐标、复利、固定增加与数据点样式；子元素可用 .grid/.axis/.compound/.fixed/.point/.label/.tick。
class .nt-controls：局部交互控件组；range、按钮及输出位于其内。
class .nt-amount：第 5 年关键金额的展示数字。
variant opening：开篇使用偏暖纸色、左缘酒红色带与更强的标题对比。
默认：不设 data-variant；冷白纸面、细规则线与局部编辑裁切感，无外部图片依赖。
品牌：无。
==== /INTERFACE ==== */

@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("style/fonts/library/barlow-condensed/face-0.ttf");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("style/fonts/library/barlow-condensed/face-1.ttf");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("style/fonts/library/barlow-condensed/face-2.ttf");
  font-weight: 800;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("style/fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("style/fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("style/fonts/library/inter/face-1.ttf");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

:root {
  --bg: #f3f1ee;
  --text: #11100f;
  --muted: #67615c;
  --focus: #254d9b;
  --accent: #8d1735;
  --compound: #8d1735;
  --fixed: #254d9b;
  --line: #1c1917;
  --line-soft: rgba(28, 25, 23, 0.18);
  --paper-light: rgba(255, 255, 255, 0.66);
  --font-sans: "NTF-inter", "NTF-noto-sans-sc", sans-serif;
  --font-title: "NTF-barlow-condensed", "NTF-noto-sans-sc", sans-serif;
  --font-number: "NTF-inter", "NTF-noto-sans-sc", sans-serif;
  --fs-h1: 112px;
  --fs-h2: 58px;
  --fs-lead: 32px;
  --fs-body: 24px;
  --fs-sec: 20px;
  --fs-label: 17px;
  --fs-tick: 14px;
  --space-1: 8px;
  --space-2: 16px;
  --space-3: 24px;
  --space-4: 40px;
  --space-5: 64px;
  --space-6: 96px;
}

html[data-variant="opening"] {
  --bg: #eee9e2;
  --text: #0c0b0a;
  --muted: #5f5954;
  --line-soft: rgba(20, 17, 15, 0.2);
}

#stage {
  color: var(--text);
  background-color: var(--bg);
  background-image:
    linear-gradient(90deg, transparent 0 7.9%, var(--line-soft) 7.9% calc(7.9% + 1px), transparent calc(7.9% + 1px)),
    linear-gradient(90deg, transparent 0 91.8%, var(--line-soft) 91.8% calc(91.8% + 1px), transparent calc(91.8% + 1px)),
    linear-gradient(180deg, var(--paper-light), transparent 38%);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: 1.55;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

html[data-variant="opening"] #stage {
  background-image:
    linear-gradient(90deg, var(--accent) 0 18px, transparent 18px),
    linear-gradient(90deg, transparent 0 7.9%, var(--line-soft) 7.9% calc(7.9% + 1px), transparent calc(7.9% + 1px)),
    linear-gradient(108deg, rgba(255,255,255,0.7) 0 43%, transparent 43.1%),
    linear-gradient(180deg, rgba(255,255,255,0.34), transparent 54%);
}

.nt-title {
  margin: 0;
  color: var(--text);
  font-family: var(--font-title);
  font-size: var(--fs-h1);
  font-weight: 400;
  font-style: normal;
  line-height: 0.91;
  letter-spacing: -0.045em;
  text-wrap: balance;
  font-synthesis: none;
}

.nt-title:lang(en),
.nt-title [lang^="en"] {
  font-family: "NTF-barlow-condensed", sans-serif;
  font-weight: 400;
  letter-spacing: -0.035em;
  text-transform: uppercase;
}

.nt-title:lang(zh),
.nt-title [lang^="zh"] {
  font-family: "NTF-noto-sans-sc", sans-serif;
  font-weight: 300;
  line-height: 1.02;
  letter-spacing: -0.055em;
}

html[data-variant="opening"] .nt-title {
  font-size: clamp(96px, 8.1vw, 130px);
  line-height: 0.88;
}

.nt-body {
  margin: 0;
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  font-weight: 400;
  line-height: 1.58;
  letter-spacing: 0;
  text-wrap: pretty;
  font-synthesis: none;
}

.nt-body + .nt-body { margin-top: 0.8em; }

.nt-lead {
  margin: 0;
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-lead);
  font-weight: 400;
  line-height: 1.38;
  letter-spacing: -0.018em;
  text-wrap: balance;
}

.nt-number {
  font-family: var(--font-number);
  font-weight: 650;
  font-style: normal;
  font-variant-numeric: lining-nums tabular-nums;
  font-feature-settings: "lnum" 1, "tnum" 1, "zero" 1;
  letter-spacing: -0.03em;
  white-space: nowrap;
  font-synthesis: none;
}

.nt-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.75em;
  margin: 0;
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.nt-kicker::before {
  content: "";
  inline-size: 44px;
  block-size: 2px;
  flex: 0 0 auto;
  background: var(--accent);
}

.nt-rule {
  width: 100%;
  height: 1px;
  margin: var(--space-3) 0;
  border: 0;
  background: var(--line);
}

.nt-formula {
  color: var(--text);
  font-family: var(--font-number);
  font-size: var(--fs-h2);
  font-weight: 500;
  line-height: 1.12;
  letter-spacing: -0.045em;
  font-variant-numeric: lining-nums tabular-nums;
  font-synthesis: none;
}

.nt-formula strong,
.nt-formula .is-emphasis {
  color: var(--accent);
  font-weight: 750;
}

.nt-note {
  color: var(--muted);
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  line-height: 1.5;
}

.nt-label {
  color: var(--muted);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 600;
  line-height: 1.4;
}

.nt-data-table {
  width: 100%;
  border-collapse: collapse;
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  line-height: 1.35;
}

.nt-data-table th,
.nt-data-table td {
  padding: 12px 14px;
  border-bottom: 1px solid var(--line-soft);
  text-align: left;
  vertical-align: middle;
}

.nt-data-table thead th {
  border-top: 2px solid var(--line);
  border-bottom: 1px solid var(--line);
  font-weight: 750;
  letter-spacing: 0.055em;
}

.nt-data-table tbody tr:last-child td { border-bottom: 2px solid var(--line); }

.nt-data-table td.is-number,
.nt-data-table th.is-number {
  font-family: var(--font-number);
  font-variant-numeric: lining-nums tabular-nums;
  text-align: right;
}

svg.nt-growth-chart {
  color: var(--text);
  overflow: visible;
  font-family: var(--font-number);
}

svg.nt-growth-chart .grid {
  fill: none;
  stroke: var(--line-soft);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

svg.nt-growth-chart .axis,
svg.nt-growth-chart .baseline {
  fill: none;
  stroke: var(--line);
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}

svg.nt-growth-chart .compound,
svg.nt-growth-chart .growth {
  fill: none;
  stroke: var(--compound);
  stroke-width: 6;
  stroke-linecap: square;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

svg.nt-growth-chart .fixed,
svg.nt-growth-chart .principal {
  fill: none;
  stroke: var(--fixed);
  stroke-width: 4;
  stroke-linecap: square;
  stroke-linejoin: miter;
  vector-effect: non-scaling-stroke;
}

svg.nt-growth-chart .point {
  fill: var(--bg);
  stroke: var(--compound);
  stroke-width: 4;
  vector-effect: non-scaling-stroke;
}

svg.nt-growth-chart .point.fixed { stroke: var(--fixed); }

svg.nt-growth-chart .label {
  fill: var(--text);
  font-size: var(--fs-label);
  font-weight: 650;
  font-variant-numeric: lining-nums tabular-nums;
}

svg.nt-growth-chart .tick {
  fill: var(--muted);
  font-size: var(--fs-tick);
  font-weight: 500;
  font-variant-numeric: lining-nums tabular-nums;
}

.nt-controls {
  --control-surface: rgba(255, 255, 255, 0.58);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  line-height: 1.35;
}

.nt-controls label { font-weight: 700; }

.nt-controls button,
.nt-controls input,
.nt-controls select,
.nt-controls output {
  color: var(--text);
  font: inherit;
}

.nt-controls button,
.nt-controls select {
  min-height: 50px;
  border: 1.5px solid var(--line);
  border-radius: 0;
  background: var(--control-surface);
  font-weight: 700;
}

.nt-controls button {
  padding: 11px 22px;
  box-shadow: 5px 5px 0 var(--line);
  cursor: pointer;
}

.nt-controls select { padding: 9px 13px; }

.nt-controls button:hover {
  border-color: var(--accent);
  color: var(--accent);
  box-shadow: 5px 5px 0 var(--accent);
}

.nt-controls button:active {
  transform: translate(3px, 3px);
  box-shadow: 2px 2px 0 var(--accent);
}

.nt-controls input[type="range"] {
  min-width: 280px;
  height: 34px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  accent-color: var(--accent);
  cursor: pointer;
}

.nt-controls input[type="range"]::-webkit-slider-runnable-track {
  height: 4px;
  background: var(--line);
}

.nt-controls input[type="range"]::-webkit-slider-thumb {
  width: 24px;
  height: 34px;
  margin-top: -15px;
  border: 2px solid var(--text);
  border-radius: 0;
  background: var(--accent);
  -webkit-appearance: none;
  appearance: none;
}

.nt-controls input[type="range"]::-moz-range-track {
  height: 4px;
  border: 0;
  background: var(--line);
}

.nt-controls input[type="range"]::-moz-range-thumb {
  width: 22px;
  height: 32px;
  border: 2px solid var(--text);
  border-radius: 0;
  background: var(--accent);
}

.nt-controls button[aria-pressed="true"],
.nt-controls [aria-selected="true"] {
  border-color: var(--accent);
  background: var(--accent);
  color: #ffffff;
}

.nt-controls button:focus-visible,
.nt-controls input:focus-visible,
.nt-controls select:focus-visible,
.nt-controls a:focus-visible {
  outline: 4px solid var(--focus);
  outline-offset: 5px;
}

.nt-amount {
  display: inline-block;
  color: var(--accent);
  font-family: var(--font-number);
  font-size: clamp(72px, 6.5vw, 108px);
  font-weight: 650;
  line-height: 0.95;
  letter-spacing: -0.065em;
  font-variant-numeric: lining-nums tabular-nums;
  white-space: nowrap;
  font-synthesis: none;
}

@media (prefers-contrast: more) {
  :root {
    --muted: #3f3a36;
    --line-soft: rgba(17, 16, 15, 0.34);
  }

  .nt-controls button,
  .nt-controls select {
    background: var(--bg);
    border-width: 2px;
  }

  svg.nt-growth-chart .grid { stroke-width: 1.5; }
}

@media (prefers-reduced-motion: reduce) {
  .nt-controls *,
  .nt-growth-chart * {
    scroll-behavior: auto;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
